"use client";

import type { CSSProperties } from "react";
import { useId } from "react";
import { flushSync } from "react-dom";
import { startMorphViewTransition } from "@/components/control-ui/extensions/view-transition";

// trigger wears shared name while closed, surface while open. That alternation is whole contract:
// View Transitions API aborts outright when two live elements claim one name at capture, which is exactly what a
// portalled popup mounting over still-present trigger would do. Matching is by name, not tree position, so it
// crosses portals and top layer. unnamed trigger stays uncaptured and keeps painting under overlay —
// hide it with data-[popup-open]:opacity-0 when it should BECOME surface instead.
export type UseMorphTransitionOptions = {
  /** Open state of surface — decides which end of pair currently owns shared name. */
  open: boolean;
  /** Override generated name; only needed when trigger and surface live in separate React trees. */
  name?: string;
};

export type MorphAnchorProps = {
  className: string | undefined;
  style: CSSProperties | undefined;
};

export type UseMorphTransitionResult = {
  /** Wraps state change that opens or closes surface. Falls through untouched when morphing is off. */
  morph: (update: () => void) => void;
  triggerProps: MorphAnchorProps;
  surfaceProps: MorphAnchorProps;
};

type MorphStyle = CSSProperties & Record<"--morph-name", string>;

const MORPH_CLASS = "morph-surface";
const INERT_ANCHOR: MorphAnchorProps = { className: undefined, style: undefined };

// view-transition-name takes custom-ident; useId ships delimiters (:r1:, «r1») that are not valid idents.
function toCustomIdent(id: string) {
  return `aui-morph-${id.replace(/[^a-zA-Z0-9_-]/g, "")}`;
}

export function useMorphTransition({ open, name }: UseMorphTransitionOptions): UseMorphTransitionResult {
  const generatedId = useId();
  const morphName = name ?? toCustomIdent(generatedId);

  const style: MorphStyle = { "--morph-name": morphName };
  const anchor: MorphAnchorProps = { className: MORPH_CLASS, style };

  // browser snapshots before `update` and again right after it returns, so React's async commit would capture same frame twice
  function morph(update: () => void) {
    startMorphViewTransition(() => flushSync(update));
  }

  return {
    morph,
    triggerProps: open ? INERT_ANCHOR : anchor,
    surfaceProps: open ? anchor : INERT_ANCHOR,
  };
}

/* view-page-rise — page transition preset via browser View Transitions API (extensions/view-transition.ts), NOT React's experimental <ViewTransition>.
 * Page body (content+ToC) carries docs-page name so only it animates: old rises out (down+blur/fade), new enters from above. */
:root {
  --view-transition-page-distance: calc(var(--spacing) * 4);
  --view-transition-page-blur: 20px;
}

/* Opt root OUT of transition (override UA implicit root name): a participating element paints into the overlay and stops being hit-testable — root captured meant the whole doc went inert, every click landed on <html>.
 * Un-naming root keeps shell (sidebar/header/theme drawer) live: swaps real-time, stays clickable mid-transition.
 * Sidebar's track-highlight pill slides itself instead of being frozen/interpolated by the snapshot; only the named page body is captured. */
:root {
  view-transition-name: none;
}

/* Transition overlay covers viewport during animation; pointer-events:none keeps live (non-participating) DOM underneath clickable.
 * Clicks on captured page body handled by extensions/view-transition.ts (skips running transition on first pointerdown, re-targets swallowed click). */
::view-transition {
  pointer-events: none;
}

.view-page {
  view-transition-name: docs-page;
}

/* Keep exchange within one --duration-slow: navigation is workflow, not showcase — longer reads as lag, widens the non-interactive snapshot window. */
::view-transition-group(docs-page) {
  animation-duration: var(--duration-slow);
  animation-timing-function: var(--ease-emphasized);
}

::view-transition-old(docs-page) {
  animation: aui-view-page-rise-old var(--duration-fast) var(--ease-standard) both;
}

::view-transition-new(docs-page) {
  animation: aui-view-page-rise-new var(--duration-slow) var(--ease-emphasized) both;
}

/* Fallback for engines ignoring root un-naming: shell swaps instantly inside snapshot instead of cross-fading; dead rules when root opt-out applies.
 * Sidebar's active pill deliberately has NO view-transition-name — shell live, track-highlight's own slide handles it.
 * Snapshot-interpolated pill would double-animate against that slide, visibly jump when transition skipped mid-flight. */
::view-transition-old(root),
::view-transition-new(root) {
  animation: none;
}

@keyframes aui-view-page-rise-old {
  from {
    opacity: 1;
    filter: blur(0);
    translate: 0 0;
  }
  to {
    opacity: 0;
    filter: blur(var(--view-transition-page-blur));
    translate: 0 var(--view-transition-page-distance);
  }
}

@keyframes aui-view-page-rise-new {
  from {
    opacity: 0;
    filter: blur(var(--view-transition-page-blur));
    translate: 0 calc(var(--view-transition-page-distance) * -1);
  }
  to {
    opacity: 1;
    filter: blur(0);
    translate: 0 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  ::view-transition-old(docs-page),
  ::view-transition-new(docs-page) {
    animation: none;
  }
}

:root[data-motion="reduced"]::view-transition-old(docs-page),
:root[data-motion="reduced"]::view-transition-new(docs-page) {
  animation: none;
}

/* morph-surface — shared-element morph preset for startMorphViewTransition() (extensions/view-transition.ts).
 * Trigger and surface carry the same --morph-name at opposite ends of one state change; the browser interpolates
 * the box between the two rects. CSS-native layoutId: no FLIP measurement, no animation runtime, no portal juggling.
 * The name must be held by exactly ONE live element per capture — useMorphTransition gates it on open state. */
.morph-surface {
  view-transition-name: var(--morph-name);
  view-transition-class: aui-morph;
}

/* A morph is element-scoped: the page body must not be captured alongside it or view-page-rise replays behind
 * the morphing box. Driver sets the attribute before the old snapshot and clears it once the transition settles. */
:root[data-view-transition="morph"] .view-page {
  view-transition-name: none;
}

/* view-transition-class groups every morph pair under one rule instead of a per-name rule the CSS cannot know.
 * Engines without it fall back to the UA default group animation — still a morph, just untuned; nothing to guard. */
::view-transition-group(.aui-morph) {
  animation-duration: var(--duration-slow);
  animation-timing-function: var(--ease-emphasized);
}

/* Snapshots render at natural size, centred in the interpolating box, instead of stretching between two very
 * different aspect ratios — content stays crisp and the box does the travelling (container-transform read). */
::view-transition-old(.aui-morph),
::view-transition-new(.aui-morph) {
  width: 100%;
  height: 100%;
  object-fit: none;
  object-position: center;
}

/* Old leaves early, new fades across the full travel: content settles as the box lands rather than before it. */
::view-transition-old(.aui-morph) {
  animation: aui-morph-fade-out var(--duration-fast) var(--ease-standard) both;
}

::view-transition-new(.aui-morph) {
  animation: aui-morph-fade-in var(--duration-slow) var(--ease-emphasized) both;
}

@keyframes aui-morph-fade-out {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}

@keyframes aui-morph-fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

/* Driver already skips the transition under either signal; these keep a hand-rolled startViewTransition() honest. */
@media (prefers-reduced-motion: reduce) {
  ::view-transition-group(.aui-morph),
  ::view-transition-old(.aui-morph),
  ::view-transition-new(.aui-morph) {
    animation: none;
  }
}

:root[data-motion="reduced"]::view-transition-group(.aui-morph),
:root[data-motion="reduced"]::view-transition-old(.aui-morph),
:root[data-motion="reduced"]::view-transition-new(.aui-morph) {
  animation: none;
}

// Two things naive startViewTransition() gets wrong in router-driven app, fixed here: completion stays pending until
// finishPageViewTransition() so browser snapshots NEW page, and transition started mid-flight skips running one.
const FINISH_TIMEOUT_MS = 500;

// lets CSS preset un-name page-level participants while element morph runs
const MORPH_ATTRIBUTE = "data-view-transition";

let finishTransition: (() => void) | null = null;
let activeTransition: ViewTransition | null = null;
let activeMorph: ViewTransition | null = null;

export function supportsViewTransition() {
  return typeof document !== "undefined" && typeof document.startViewTransition === "function";
}

export function motionReduced() {
  return (
    document.documentElement.getAttribute("data-motion") === "reduced" || window.matchMedia("(prefers-reduced-motion: reduce)").matches
  );
}

/** Call once new view is on screen. */
export function finishPageViewTransition() {
  finishTransition?.();
  finishTransition = null;
}

export function startPageViewTransition(update: () => void, { finishTimeout = FINISH_TIMEOUT_MS }: { finishTimeout?: number } = {}) {
  if (!supportsViewTransition() || motionReduced()) {
    update();
    return;
  }

  // jump any mid-flight transition to its end state, so this navigation snapshots live DOM instead of waiting
  activeTransition?.skipTransition();
  finishPageViewTransition();

  const transition = document.startViewTransition(
    () =>
      new Promise<void>((resolve) => {
        finishTransition = resolve;
        update();
        // blocked or cancelled navigation would otherwise leave page frozen under snapshot
        window.setTimeout(() => {
          if (finishTransition === resolve) {
            finishTransition = null;
            resolve();
          }
        }, finishTimeout);
      }),
  );

  activeTransition = transition;

  // Captured elements paint into overlay and stop being hit-testable, so press during transition would be eaten.
  // Skipping to end brings live DOM back, but that press's click already targeted root — re-target it to whatever now sits under pointer.
  const interrupt = () => {
    transition.skipTransition();
    window.addEventListener(
      "click",
      (click) => {
        if (click.target !== document.documentElement && click.target !== document.body) return;
        const actionable = document.elementFromPoint(click.clientX, click.clientY)?.closest("a, button");
        if (actionable instanceof HTMLElement) actionable.click();
      },
      { capture: true, once: true },
    );
  };
  window.addEventListener("pointerdown", interrupt, { capture: true, once: true });

  // ready/finished reject on mid-flight skip — expected, not error
  transition.ready.catch(() => {});
  transition.finished
    .catch(() => {})
    .finally(() => {
      window.removeEventListener("pointerdown", interrupt, { capture: true });
      if (activeTransition === transition) activeTransition = null;
    });
}

// Trigger and surface carry SAME view-transition-name at opposite ends of one state change and browser
// interpolates box between them. `update` must apply its DOM change synchronously — React callers wrap it in flushSync.
// Enforced here: page-level names are un-named for transition's lifetime (they would replay page preset behind the
// morph), and second morph skips first rather than fighting it over overlay. Uniqueness of shared name stays
// caller's job — two live elements holding one name abort transition outright.
export function startMorphViewTransition(update: () => void) {
  if (!supportsViewTransition() || motionReduced()) {
    update();
    return;
  }

  activeMorph?.skipTransition();
  document.documentElement.setAttribute(MORPH_ATTRIBUTE, "morph");

  const transition = document.startViewTransition(update);
  activeMorph = transition;

  // ready/finished reject when skipped mid-flight — expected interruption, not error.
  transition.ready.catch(() => {});
  transition.finished
    .catch(() => {})
    .finally(() => {
      if (activeMorph !== transition) return;
      activeMorph = null;
      document.documentElement.removeAttribute(MORPH_ATTRIBUTE);
    });
}
